    lines.push((isChinese ? '語法：' : 'Syntax: ') + '`' + usage.syntax + '`');
    lines.push((isChinese ? '呼叫類別：' : 'Invocation class: ') + '`' + usage.invocation_class + '`');
    lines.push((isChinese ? '最高 authority：' : 'Maximum authority: ') + '`' + usage.effect_authority + '`');
